const email = $json;
// n8n IMAP node (format: simple) zwraca naglowki w polu "metadata",
// a nie "headers" - obsluguj oba warianty.
const headers = email.metadata || email.headers || {};

let messageId =
  email.messageId ||
  headers['message-id'] ||
  headers['Message-ID'] ||
  '';

if (!messageId) {
  const parts = [];
  if (email.date) parts.push(String(email.date));
  if (email.subject) parts.push(String(email.subject));
  messageId = parts.join(' - ');
}

let from = '';
if (email.from && typeof email.from === 'object') {
  from =
    email.from.text ||
    (email.from.value && email.from.value[0] && email.from.value[0].address) ||
    '';
} else if (email.from) {
  from = String(email.from);
}

if (!messageId) {
  throw new Error('Brak messageId - backend zwrocilby 400 Bad Request');
}

return {
  json: {
    messageId: String(messageId),
    from: from,
    subject: email.subject || '',
    textBody: email.textPlain || email.text || '',
    htmlBody: email.textHtml || email.html || '',
  },
};
